(() => {
  "use strict";
  const ui = { login: document.querySelector("#loginView"), dashboard: document.querySelector("#dashboard"), form: document.querySelector("#loginForm"), email: document.querySelector("#email"), password: document.querySelector("#password"), error: document.querySelector("#loginError"), logout: document.querySelector("#logoutButton"), name: document.querySelector("#welcomeName"), details: document.querySelector("#accountDetails"), role: document.querySelector("#roleBadge"), appsPanel: document.querySelector("#applicationsPanel"), offersPanel: document.querySelector("#offersPanel"), applications: document.querySelector("#applications"), quotes: document.querySelector("#quotes"), offers: document.querySelector("#offers") };
  const labels = { driver: "Driver", broker: "Broker", shipper: "Direct shipper", owner_operator: "Owner-operator", company_driver: "Company driver", new: "New", reviewing: "Reviewing", approved: "Approved", declined: "Declined", quoted: "Quoted", booked: "Booked", submitted: "Submitted", offered: "Offer available", accepted: "Accepted", phone_screen: "Phone call", docs_requested: "Documents requested", docs_received: "Documents received", documents_processed: "Documents processed", sold_hired_partner: "Hired by partner", callback_hired: "Hiring callback", orientation_complete: "Orientation complete" };
  const escapeText = (value) => String(value || "");
  function status(value) { const span = document.createElement("span"); span.className = `status ${value}`; span.textContent = labels[value] || value; return span; }
  function empty(container, text) { const div = document.createElement("div"); div.className = "empty"; div.textContent = text; container.replaceChildren(div); }
  function item(title, lines, badge, actions) { const row = document.createElement("article"); row.className = "item"; const copy = document.createElement("div"); const h3 = document.createElement("h3"); h3.textContent = title; copy.append(h3); lines.forEach((line) => { const p = document.createElement("p"); p.textContent = line; copy.append(p); }); row.append(copy, badge); if (actions) row.append(actions); else row.append(document.createElement("span")); return row; }
  function uploadForm(app, kind, uploaded) { const form = document.createElement("form"); form.className = "document-upload"; form.dataset.application = app.id; form.dataset.document = kind; const heading = document.createElement("strong"); heading.textContent = kind === "cdl" ? "CDL" : "DOT medical card"; const state = document.createElement("span"); state.className = uploaded ? "document-state received" : "document-state"; state.textContent = uploaded ? "Received" : "Needed"; const file = document.createElement("input"); file.type = "file"; file.name = "file"; file.accept = "application/pdf,image/jpeg,image/png"; file.required = true; file.setAttribute("aria-label", `Choose ${heading.textContent} file`); form.append(heading, state); const consent = document.createElement("label"); consent.className = "upload-consent"; const checkbox = document.createElement("input"); checkbox.type = "checkbox"; checkbox.name = "consent"; checkbox.required = true; const consentText = document.createElement("span"); consentText.textContent = "I agree to securely share this document with Worldwide Cargo Express for driver recruiting."; consent.append(checkbox, consentText); const button = document.createElement("button"); button.type = "submit"; button.textContent = uploaded ? "Replace file" : "Upload"; const message = document.createElement("p"); message.className = "upload-message"; form.append(file, consent, button, message); return form; }
  function applicationItem(app) { const row = document.createElement("article"); row.className = "application-item"; const head = document.createElement("div"); head.className = "application-head"; const copy = document.createElement("div"); const title = document.createElement("h3"); title.textContent = `${labels[app.driver_type] || "Driver"} application`; const detail = document.createElement("p"); detail.textContent = `Submitted ${new Date(app.submitted_at || app.created_at).toLocaleDateString()} · ID ${app.id.slice(0, 8).toUpperCase()}`; copy.append(title, detail); head.append(copy, status(app.orientation_completed_at ? "orientation_complete" : app.recruiting_stage || app.review_status || app.status)); const intro = document.createElement("p"); intro.className = "document-intro"; intro.textContent = app.recruiting_stage === "docs_requested" ? "Your recruiter is ready for your documents. Upload a clear CDL and current medical card below." : "You can securely upload or replace your driver documents here at any time."; const forms = document.createElement("div"); forms.className = "document-forms"; forms.append(uploadForm(app, "cdl", Boolean(app.cdl_document_uploaded_at)), uploadForm(app, "medical-card", Boolean(app.medical_card_uploaded_at))); row.append(head, intro, forms); return row; }
  function render(data) {
    const account = data.account; ui.name.textContent = `Welcome, ${account.fullName.split(/\s+/u)[0]}`; ui.details.textContent = `${account.email} · ${account.phone || "No phone entered"}`; ui.role.textContent = account.role === "driver" ? `${labels[account.driverType] || "Driver"} account` : `${labels[account.role]} account`;
    ui.appsPanel.hidden = account.role !== "driver"; ui.offersPanel.hidden = account.role !== "driver";
    if (!data.applications.length) empty(ui.applications, "No driver application is connected to this account yet."); else { ui.applications.replaceChildren(...data.applications.map(applicationItem)); }
    if (!data.quotes.length) empty(ui.quotes, "No quote requests yet."); else { ui.quotes.replaceChildren(...data.quotes.map((quote) => item(`${escapeText(quote.pickup_city)}, ${escapeText(quote.pickup_state)} → ${escapeText(quote.delivery_city)}, ${escapeText(quote.delivery_state)}`, [quote.commodity || "Freight details pending", `${quote.equipment || "Equipment pending"} · Updated ${new Date(quote.updated_at).toLocaleDateString()}`], status(quote.status)))); }
    if (!data.offers.length) empty(ui.offers, "No offers have been matched to you yet."); else { ui.offers.replaceChildren(...data.offers.map((offer) => { const actions = document.createElement("div"); actions.className = "offer-actions"; if (offer.status === "offered") { for (const choice of ["accepted", "declined"]) { const button = document.createElement("button"); button.type = "button"; button.dataset.offer = offer.id; button.dataset.status = choice; button.className = choice === "accepted" ? "accept" : ""; button.textContent = choice === "accepted" ? "Accept" : "Decline"; actions.append(button); } } const rate = offer.offered_rate_cents == null ? "Rate to be discussed" : new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" }).format(offer.offered_rate_cents / 100); return item(`${escapeText(offer.pickup_city)}, ${escapeText(offer.pickup_state)} → ${escapeText(offer.delivery_city)}, ${escapeText(offer.delivery_state)}`, [`${rate} · ${offer.equipment || "Equipment pending"}`, offer.notes || offer.commodity || "No additional notes"], status(offer.status), actions); })); }
  }
  async function load() { const response = await fetch("/api/account/me", { cache: "no-store" }); if (response.status === 401) { ui.login.hidden = false; ui.dashboard.hidden = true; ui.logout.hidden = true; return; } if (!response.ok) throw new Error("Unable to load your account."); render(await response.json()); ui.login.hidden = true; ui.dashboard.hidden = false; ui.logout.hidden = false; }
  ui.form.addEventListener("submit", async (event) => { event.preventDefault(); ui.error.textContent = ""; const button = ui.form.querySelector("button"); button.disabled = true; try { const response = await fetch("/api/account/login", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ email: ui.email.value, password: ui.password.value }) }); const data = await response.json(); if (!response.ok) throw new Error(data.error || "Unable to sign in."); ui.password.value = ""; await load(); } catch (error) { ui.error.textContent = error.message; } finally { button.disabled = false; } });
  ui.logout.addEventListener("click", async () => { await fetch("/api/account/logout", { method: "POST" }); location.reload(); });
  ui.offers.addEventListener("click", async (event) => { const button = event.target.closest("button[data-offer]"); if (!button) return; button.disabled = true; const response = await fetch(`/api/account/offers/${button.dataset.offer}`, { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ status: button.dataset.status }) }); if (response.ok) await load(); else button.disabled = false; });
  ui.applications.addEventListener("submit", async (event) => { const form = event.target.closest("form[data-document]"); if (!form) return; event.preventDefault(); const button = form.querySelector("button"), message = form.querySelector(".upload-message"), file = form.querySelector('input[type="file"]').files?.[0], consent = form.querySelector('input[name="consent"]'); if (!file || !consent.checked) { message.textContent = "Choose a file and confirm consent."; return; } if (file.size > 5 * 1024 * 1024) { message.textContent = "Choose a file smaller than 5 MB."; return; } const body = new FormData(); body.append("file", file); body.append("consent", "yes"); button.disabled = true; message.textContent = "Uploading securely…"; try { const response = await fetch(`/api/account/applications/${form.dataset.application}/documents/${form.dataset.document}`, { method: "POST", body }); const data = await response.json(); if (!response.ok) throw new Error(data.error || "Upload failed."); await load(); } catch (error) { message.textContent = error.message || "Upload failed. Please try again."; button.disabled = false; } });
  load().catch(() => { ui.error.textContent = "Unable to load your account right now."; });
})();
